// CSD_RATIONALE_BEGIN
// Root-cause diagnosis: The best result (Attempt 1, 40.8%) had a constrained branch that
// never fired because `next == "<<"` is an exact-token equality check that fails for Qwen's
// tokenizer — it emits the delimiter as " <<" (space-prefixed) or split across tokens.
// Evaluation confirmed 0/49 examples used the constrained branch.
//
// Failure breakdown:
//   - 3 malformed cases: model wrote `{mult}`, `{n0}`, `{r}` (template braces), `**`
//     (Python power), `//` (floor division), or `if-else` (Python conditional) — all
//     grammar-rejected by the math expression parser.
//   - 27 wrong-but-valid cases: syntactically valid but semantically wrong formulas.
//
// Fix:
//   1. Replace `next == "<<"` with `RenderedEndsWith(generated, "<<")` so the constrained
//      branch fires correctly regardless of tokenizer splitting.
//   2. `AdaptiveConstrainedStep` inside spans hard-masks to grammar-valid tokens, preventing
//      `{var}`, `**`, `//`, and `if-else` — fixing the 3 malformed cases.
//   3. Updated guidance explicitly discourages Python-style syntax and template braces.
//
// The rest of the strategy is identical to Attempt 1 (best): unconstrained free generation
// outside spans, `AdaptiveConstrainedStep` inside spans, `CloseConstrainedSpan` on
// completeness, `CloseSpanWithinBudget` at budget pressure.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//
//    Outside-span branch: `insideConstrainedOut` stays false until `RenderedEndsWith` fires.
//    At that point `EnterObservedConstrainedSpan` sets `currentConstrainedOut := []`.
//    The method precondition provides `parser.IsValidPrefix([])`, so the invariant holds.
//
//    CloseConstrainedSpan branch: postcondition sets `insideConstrainedOut := false`,
//    making the implication vacuously true; `currentConstrainedOut := []`.
//
//    CloseSpanWithinBudget branch: postcondition directly guarantees
//    `insideOut ==> parser.IsValidPrefix(currentOut)` for both closed and still-open cases.
//
//    AdaptiveConstrainedStep + AppendConstrainedToken branch: `AdaptiveConstrainedStep`
//    returns a grammar-valid next token under hard mask. `AppendConstrainedToken` extends
//    `currentConstrainedOut` by that token; by the definition of `IsValidPrefix`, extending
//    a valid prefix by a valid next token yields another valid prefix.
//
// 2. progress: `|generated| <= |generatedPrefix| + steps`
//
//    Outside-span EOS path: `steps` grows by 1, `generated` unchanged.
//    `|generated| <= |generatedPrefix| + steps_old < |generatedPrefix| + steps_new`. ✓
//
//    Outside-span non-EOS path: `steps` grows by 1, `|generated|` grows by 1.
//    `|generated_new| = |generated_old| + 1 <= (|generatedPrefix| + steps_old) + 1 = |generatedPrefix| + steps_new`. ✓
//
//    CloseConstrainedSpan path: `steps` grows by 1; `generated` grows by at most 1 (">>").
//    Same arithmetic as non-EOS outside-span. ✓
//
//    CloseSpanWithinBudget path: `closeBudget = maxSteps - steps`. Helper postcondition:
//    `|generatedOut| <= |generated| + closeBudget`. After `steps := maxSteps`:
//    `|generated| <= |generatedPrefix| + steps_old + (maxSteps - steps_old) = |generatedPrefix| + maxSteps = |generatedPrefix| + steps`. ✓
//
//    AdaptiveConstrainedStep non-EOS path: `steps` grows by 1; `AppendConstrainedToken`
//    appends one token to `generated`.
//    `|generated_new| = |generated_old| + 1 <= |generatedPrefix| + steps_old + 1 = |generatedPrefix| + steps_new`. ✓
//
//    AdaptiveConstrainedStep EOS path: `steps` grows by 1, `generated` unchanged. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap each intermediate computed value and the final answer inside << >>. Inside << >>, use only +, -, *, / and parentheses. Write variable names exactly as they appear in the problem without curly braces (write n1 not {n1}). Never use ** or // or if-else inside << >>. The final << >> must contain the simplest correct algebraic formula.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := eg;
      insideConstrainedOut := ei;
      currentConstrainedOut := ec;
    }
  } else {
    if parser.IsCompletePrefix(currentConstrainedOut) {
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

